#pragma once
#include <circuit/contracts/ids.hpp>
#include <array>
#include <cstdint>
#include <optional>
#include <span>
#include <string>
#include <string_view>
#include <utility>
#include <vector>

// The block registry circuit-blocks-1: every block state of every supported
// version, generated by tools/compile_block_registry.py from public data
// (PrismarineJS minecraft-data, MIT, at the pinned commit).
//
// An internal block is a block schema: a name with its properties and their
// values. A block whose schema differs between versions has one internal
// block per schema; the older one is named `<name>@<release>`. Internal
// states number the states of all internal blocks from 1, in a fixed order
// that only grows, so records that store them stay valid. Each version maps
// its wire state ids to internal states and back.
namespace circuit::gameplay::registry {

using Property = std::pair<std::string, std::string>;

enum class Collision : std::uint8_t { empty = 0, partial = 1, full = 2 };
// The tool kind that mines a block faster (its mineable tag).
enum class Tool : std::uint8_t { none, pickaxe, axe, shovel, hoe };
// Tier value of a block that only tools of another kind harvest.
inline constexpr std::uint8_t other_tool_tier = 255;

struct BlockInfo {
    std::string_view name; // without namespace, e.g. "oak_log"
    std::uint32_t first_state;
    std::uint32_t state_count;
    std::uint32_t default_state;
    float hardness; // negative: players cannot break it
    bool opaque;    // blocks all light and renders as a solid cube
    Tool tool;
    std::uint8_t tier; // lowest tier of `tool` that harvests the block; 0 for any tool
    float resistance;  // blast resistance
};

// A box of a collision shape, in block coordinates (0 to 1; fences, walls
// and piston heads reach beyond their cell).
struct Box {
    double min_x, min_y, min_z, max_x, max_y, max_z;
};

std::string_view id() noexcept;
// Internal states are 1 to state_count().
std::uint32_t state_count() noexcept;
std::uint32_t block_count() noexcept;
// Internal block `index` (below block_count()).
BlockInfo block(std::uint32_t index) noexcept;
std::optional<std::uint32_t> block_of(std::uint32_t state) noexcept;
// The name a version uses for an internal block: without the schema suffix.
std::string_view game_name(std::uint32_t block) noexcept;

// The supported releases ("1.21.8", "1.21.4"), newest first.
std::vector<std::string_view> releases();
// The internal block of `name` ("minecraft:oak_log" or "oak_log") in `release`.
std::optional<std::uint32_t> find_block(std::string_view release, std::string_view name);
// Every property of a state, in the registry order of its block.
std::vector<Property> properties(std::uint32_t state);
// "minecraft:name[key=value,...]" with every property, in key order.
std::string notation(std::uint32_t state);
// The state of `block` with the given properties; the others take the values
// of the block's default state. nullopt for unknown properties or values.
std::optional<std::uint32_t> state_of(std::uint32_t block, std::span<const Property> properties);

Collision collision(std::uint32_t state) noexcept;
// Whether the collision shape covers the whole face on that side of the cell.
bool face_covered(std::uint32_t state, contracts::Direction face) noexcept;

// Light, by the rules of tools/compile_block_registry.py (checked against a
// report of every state of both official servers): the light a state emits,
// how much it dampens light passing into it (0, 1 or 15), and for states
// whose shape occludes light, their occlusion shape (0: none).
std::uint8_t light_emission(std::uint32_t state) noexcept;
std::uint8_t light_dampening(std::uint32_t state) noexcept;
std::uint16_t light_shape(std::uint32_t state) noexcept;
// Whether a state counts for the MOTION_BLOCKING heightmap: it is solid or
// holds a fluid (rules of tools/compile_block_registry.py, checked against a
// report of every state of both official servers).
bool motion_blocking(std::uint32_t state) noexcept;
// Whether light cannot pass from a cell with occlusion shape `from` to its
// neighbor on `side` with shape `to`: the two shapes' faces between them
// together cover the face completely.
bool light_occluded(std::uint16_t from, std::uint16_t to, contracts::Direction side) noexcept;
std::uint32_t light_shape_count() noexcept;
// The 16x16 cells of one face an occlusion shape covers: bit u * 16 + v of
// the face's two other axes, in x, y, z order.
std::array<std::uint64_t, 4> light_face(std::uint16_t shape, contracts::Direction face) noexcept;

// A state's collision shape in a release (minecraft-data's
// blockCollisionShapes.json; the releases agree on every state they share
// but one).
std::span<const Box> collision_boxes(std::uint32_t state, std::string_view release) noexcept;

// Wire state ids of a release: 0 to wire_state_count(release) - 1.
std::uint32_t wire_state_count(std::string_view release) noexcept;
std::optional<std::int32_t> to_wire(std::string_view release, std::uint32_t state);
std::optional<std::uint32_t> from_wire(std::string_view release, std::int32_t wire);

} // namespace circuit::gameplay::registry
